#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    vector<int> left_sums, right_sums;
    int mid = n / 2;

    function<void(int, int)> compute_left = [&](int i, int current_sum) {
        if (i == mid) {
            left_sums.push_back(current_sum);
        } else {
            compute_left(i + 1, (current_sum + a[i]) % m);
            compute_left(i + 1, current_sum);
        }
    };

    function<void(int, int)> compute_right = [&](int i, int current_sum) {
        if (i == n) {
            right_sums.push_back(current_sum);
        } else {
            compute_right(i + 1, (current_sum + a[i]) % m);
            compute_right(i + 1, current_sum);
        }
    };

    compute_left(0, 0);
    compute_right(mid, 0);

    sort(left_sums.begin(), left_sums.end());
    left_sums.erase(unique(left_sums.begin(), left_sums.end()), left_sums.end());

    int best = 0;
    for (int val : right_sums) {
        int target = m - val;
        auto pos = lower_bound(left_sums.begin(), left_sums.end(), target);
        if (pos != left_sums.begin()) {
            int candidate = *(pos - 1) + val;
            if (candidate > best) {
                best = candidate;
            }
        } else {
            if (val > best) {
                best = val;
            }
        }
    }
    cout << best << "\n";
    return 0;
}
